class Invoke(object):
    """Invoke a callable on the target."""
    def __init__(self, func=None, args=None, kwargs=None):
        self.func = func
        self.args = args or []
        self.kwargs = kwargs or {}
    def glomit(self, target, scope):
        func = self.func
        if func is None:
            func = target
            return func()
        # evaluate args and kwargs
        args = [scope[glom](target, a, scope) if isinstance(a, (Spec, TType)) else a for a in self.args]
        kwargs = {k: scope[glom](target, v, scope) if isinstance(v, (Spec, TType)) else v for k, v in self.kwargs.items()}
        return func(target, *args, **kwargs)
    def __repr__(self):
        return 'Invoke(%r)' % self.func

